WITH exploded AS (SELECT id, plan, currency, EXPLODE_OUTER(discounts) AS val FROM price_tiers) SELECT currency, plan, ROUND(AVG(val), 2) AS avg_val, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(currency = 'USD') AS usd_events, COUNT(*) AS cnt, COUNT(CASE WHEN currency = 'EUR' THEN 1 END) AS eur_count, ROUND(SUM(val) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS val_per_basic FROM exploded GROUP BY GROUPING SETS ((currency, plan), (currency)) ORDER BY avg_val DESC NULLS LAST;
